const asList = (value) => String(value || '')
  .split(',')
  .map((part) => part.trim())
  .filter(Boolean);

const workerUrl = String($env.JOBHUNTER_WORKER_URL || '').replace(/\/$/, '');
const minScore = Number($env.JOBHUNTER_MIN_SCORE || 70);

return [{
  json: {
    runId: `n8n-${Date.now()}`,
    // test é o padrão: nenhuma candidatura é enviada até que o worker exista.
    mode: String($env.JOBHUNTER_MODE || 'test').toLowerCase(),
    workerUrl,
    autoApplyEnabled: String($env.JOBHUNTER_AUTO_APPLY || 'false').toLowerCase() === 'true',
    minScore: Number.isFinite(minScore) ? minScore : 70,
    profile: {
      targetRoles: asList($env.JOBHUNTER_TARGET_ROLES || 'desenvolvedor, software engineer'),
      requiredKeywords: asList($env.JOBHUNTER_REQUIRED_KEYWORDS || 'javascript, typescript'),
      preferredLocations: asList($env.JOBHUNTER_PREFERRED_LOCATIONS || 'remoto, remote'),
      resumeRef: String($env.JOBHUNTER_RESUME_REF || 'PREENCHER_REFERENCIA_DO_CURRICULO')
    }
  }
}];

const config = $('Carregar perfil e configuração').first().json;
const payload = $input.first().json;
const jobs = Array.isArray(payload) ? payload : (payload.jobs || payload.data?.jobs || []);

if (!Array.isArray(jobs)) {
  throw new Error('O worker deve devolver { jobs: Job[] }.');
}

return jobs.map((job) => ({ json: { ...config, job } }));

const input = $json;
const job = input.job || {};
const applyUrl = String(job.applyUrl || job.url || '').trim();
const source = String(job.source || 'unknown').trim().toLowerCase();
const externalId = String(job.externalId || applyUrl || job.title || '').trim();

if (!job.title || !applyUrl || !externalId) {
  throw new Error('Cada vaga precisa de title, applyUrl/url e externalId (ou URL única).');
}

return {
  json: {
    ...input,
    job: {
      ...job,
      source,
      externalId,
      title: String(job.title).trim(),
      company: String(job.company || 'Não informada').trim(),
      location: String(job.location || 'Não informada').trim(),
      description: String(job.description || ''),
      applyUrl
    },
    idempotencyKey: `${source}:${externalId}`
  }
};

const seen = new Set();
const unique = [];

for (const item of $input.all()) {
  const key = item.json.idempotencyKey;
  if (seen.has(key)) continue;
  seen.add(key);
  unique.push(item);
}

return unique;

const input = $json;
const job = input.job;
const profile = input.profile;
const text = `${job.title} ${job.description} ${job.location}`.toLowerCase();
const includes = (term) => text.includes(String(term).toLowerCase());

const roleHits = profile.targetRoles.filter(includes);
const requiredHits = profile.requiredKeywords.filter(includes);
const locationHits = profile.preferredLocations.filter(includes);
const score = Math.min(100, (roleHits.length * 40) + (requiredHits.length * 15) + (locationHits.length * 10));
const blockedByChallenge = Boolean(job.requiresCaptcha || job.requiresMfa || job.hasUnknownQuestions);
const eligible = input.autoApplyEnabled && Boolean(input.workerUrl) && score >= input.minScore && !blockedByChallenge;

return {
  json: {
    ...input,
    match: { score, roleHits, requiredHits, locationHits },
    reviewReason: blockedByChallenge
      ? 'CAPTCHA, MFA ou pergunta desconhecida exige intervenção humana'
      : score < input.minScore
        ? `Compatibilidade ${score} abaixo do mínimo ${input.minScore}`
        : !input.autoApplyEnabled
          ? 'Envio automático desativado'
          : !input.workerUrl
            ? 'Worker local não configurado'
            : null,
    automationDecision: eligible ? 'send' : 'review'
  }
};

return {
  json: {
    status: 'review_required',
    runId: $json.runId,
    idempotencyKey: $json.idempotencyKey,
    job: $json.job,
    match: $json.match,
    reason: $json.reviewReason || 'Revisão manual necessária'
  }
};

const response = $json;
const original = $('Pode enviar candidatura?').item.json;
const status = String(response.status || 'unknown').toLowerCase();
const needsReview = ['captcha', 'mfa', 'manual_review', 'unknown_question', 'blocked'].includes(status);

return {
  json: {
    status: needsReview ? 'review_required' : status,
    runId: original.runId,
    idempotencyKey: original.idempotencyKey,
    job: original.job,
    match: original.match,
    workerResponse: response,
    reason: needsReview ? (response.reason || 'O worker solicitou revisão humana') : undefined
  }
};
